import type { CurrencyTotals, IncomingTransaction, Report, ReportRow } from "../../types";
import { toISODate } from "../../util/dates";
import { db } from "../client";

export interface ListOptions {
  limit?: number;
  offset?: number;
}

type ReportFilter = Pick<Report, "accountId" | "from" | "to" | "categories">;

export const transactionRepo = {
  /** Inserts all rows in one statement (unnest over parallel arrays). Returns the number inserted. */
  async insertMany(accountId: string, uploadId: string, rows: IncomingTransaction[]): Promise<number> {
    if (rows.length === 0) return 0;
    const inserted = await db.query<{ id: number }>(
      `INSERT INTO transactions (account_id, upload_id, date, amount, currency, description, category, reference)
       SELECT $1, $2, * FROM unnest($3::date[], $4::bigint[], $5::char(3)[], $6::text[], $7::text[], $8::text[])
       RETURNING id`,
      [
        accountId,
        uploadId,
        rows.map((r) => r.date),
        rows.map((r) => r.amount),
        rows.map((r) => r.currency),
        rows.map((r) => r.description),
        rows.map((r) => r.category),
        rows.map((r) => r.reference),
      ],
    );
    return inserted.length;
  },

  /** Stored transactions for an account between two ISO dates, inclusive. */
  async listInRange(accountId: string, from: string, to: string): Promise<IncomingTransaction[]> {
    return db.query<IncomingTransaction>(
      `SELECT date, amount, currency, description, category, reference
         FROM transactions
        WHERE account_id = $1 AND date BETWEEN $2 AND $3`,
      [accountId, from, to],
    );
  },

  async listForReport(report: ReportFilter, options: ListOptions = {}): Promise<ReportRow[]> {
    const params: unknown[] = [report.accountId, report.from, report.to];
    let categoryFilter = "";
    if (report.categories.length > 0) {
      params.push(report.categories);
      categoryFilter = `AND category = ANY($${params.length})`;
    }
    // LIMIT NULL means no limit in Postgres.
    params.push(options.limit ?? null, options.offset ?? 0);

    return db.query<ReportRow>(
      `SELECT date, amount, currency, description, category
         FROM transactions
        WHERE account_id = $1 AND date BETWEEN $2 AND $3 ${categoryFilter}
        ORDER BY date, id
        LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params,
    );
  },

  /** Inflow and outflow per currency across all of a user's accounts, for [from, to). */
  async totalsBetween(userId: string, from: Date, to: Date): Promise<CurrencyTotals[]> {
    return db.query<CurrencyTotals>(
      `SELECT t.currency,
              count(*)::int AS count,
              COALESCE(sum(t.amount) FILTER (WHERE t.amount > 0), 0)::bigint AS inflow,
              COALESCE(sum(t.amount) FILTER (WHERE t.amount < 0), 0)::bigint AS outflow
         FROM transactions t
         JOIN accounts a ON a.id = t.account_id
        WHERE a.user_id = $1 AND t.date >= $2 AND t.date < $3
        GROUP BY t.currency
        ORDER BY t.currency`,
      [userId, toISODate(from), toISODate(to)],
    );
  },
};


--- src/ingest/parser.ts
import { IngestError } from "./errors";

/** Columns every statement must have. Header names are matched case-insensitively. */
export const REQUIRED_COLUMNS = ["date", "amount", "description"];

/** Recognised when present. Any other column is carried through and ignored. */
export const OPTIONAL_COLUMNS = ["currency", "category", "reference"];

export type RawRow = Record<string, string>;

export interface ParsedStatement {
  header: string[];
  rows: RawRow[];
}

export interface ParseOptions {
  /** Stop after this many data rows (the upload preview only needs a few). */
  limit?: number;
}

const QUOTE = '"';
const BOM = "﻿";

/**
 * Splits one CSV line into fields. Handles double-quoted fields that contain
 * commas, and "" as an escaped quote inside a quoted field.
 */
export function splitFields(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === QUOTE && line[i + 1] === QUOTE) {
        current += QUOTE;
        i++;
      } else if (ch === QUOTE) {
        inQuotes = false;
      } else {
        current += ch;
      }
    } else if (ch === QUOTE) {
      inQuotes = true;
    } else if (ch === ",") {
      fields.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  fields.push(current);
  return fields;
}

function assertShape(fields: string[], header: string[], index: number): void {
  const missingRequired = REQUIRED_COLUMNS.some((column) => !header.includes(column));
  if (missingRequired || fields.length !== header.length) {
    throw new IngestError("errors.rowShape", { row: index + 1 });
  }
}

/**
 * Parses an uploaded statement into rows keyed by lower-cased column name.
 * Values are returned exactly as written; schema.ts does the type conversion.
 */
export function parseStatement(input: string | Buffer, options: ParseOptions = {}): ParsedStatement {
  let text = typeof input === "string" ? input : input.toString("utf8");
  if (text.startsWith(BOM)) text = text.slice(BOM.length);

  const lines = text.split("\n");
  // A final newline leaves an empty string at the end.
  if (lines.length > 0 && lines[lines.length - 1] === "") lines.pop();
  if (lines.length === 0) throw new IngestError("errors.emptyFile");

  const header = lines[0].split(",").map((h) => h.toLowerCase());
  assertShape(header, header, 0);

  const limit = options.limit ?? Number.POSITIVE_INFINITY;
  const rows: RawRow[] = [];

  for (let index = 1; index < lines.length && rows.length < limit; index++) {
    const fields = splitFields(lines[index]);
    assertShape(fields, header, index);

    const row: RawRow = {};
    header.forEach((column, i) => {
      row[column] = fields[i];
    });
    rows.push(row);
  }

  return { header, rows };
}


--- src/util/dates.ts
const MINUTE_MS = 60 * 1000;
const DAY_MS = 24 * 60 * MINUTE_MS;

export function addDays(d: Date, days: number): Date {
  return new Date(d.getTime() + days * DAY_MS);
}

export function addMinutes(d: Date, minutes: number): Date {
  return new Date(d.getTime() + minutes * MINUTE_MS);
}

/** YYYY-MM-DD, in UTC. */
export function toISODate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
const DAY_FIRST = /^(\d{1,2})[/.](\d{1,2})[/.](\d{4})$/;

/**
 * Reads the date formats banks commonly use in statement exports and returns
 * an ISO date, or null if the value is not a real calendar date. Slash and dot
 * formats are read day first: 31/03/2026, 31.03.2026.
 */
export function parseStatementDate(value: string): string | null {
  let year: number;
  let month: number;
  let day: number;

  const iso = ISO_DATE.exec(value);
  const dayFirst = iso ? null : DAY_FIRST.exec(value);
  if (iso) {
    [year, month, day] = [Number(iso[1]), Number(iso[2]), Number(iso[3])];
  } else if (dayFirst) {
    [day, month, year] = [Number(dayFirst[1]), Number(dayFirst[2]), Number(dayFirst[3])];
  } else {
    return null;
  }

  // Date.UTC rolls 31/02 over into March, so check the parts survived.
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) {
    return null;
  }
  return toISODate(date);
}

export function isValidTimeZone(tz: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

/** Hour of the day (0 to 23) at instant `d`, as seen in time zone `tz`. */
export function localHour(d: Date, tz: string): number {
  const hour = new Intl.DateTimeFormat("en-GB", { timeZone: tz, hour: "numeric", hourCycle: "h23" })
    .formatToParts(d)
    .find((part) => part.type === "hour");
  return Number(hour?.value ?? 0);
}

/** The instant the week containing `d` begins, for someone in time zone `tz`. */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function startOfWeek(d: Date, tz: string): Date {
  // TODO: honour tz
  const start = new Date(d.getTime());
  // Weeks start on Monday.
  const daysSinceMonday = (start.getUTCDay() + 6) % 7;
  start.setUTCDate(start.getUTCDate() - daysSinceMonday);
  start.setUTCHours(0, 0, 0, 0);
  return start;
}

/** "2 March 2026" style, in the given locale and time zone. */
export function formatDay(d: Date, locale: string, tz = "UTC"): string {
  return new Intl.DateTimeFormat(locale, {
    timeZone: tz,
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(d);
}


--- src/notifications/rollup.ts
import { transactionRepo } from "../db/repos/transactionRepo";
import { userRepo } from "../db/repos/userRepo";
import { t } from "../i18n";
import { logger } from "../logger";
import type { User } from "../types";
import { addDays, localHour, startOfWeek } from "../util/dates";
import { sendEmail } from "./email";
import { rollupText } from "./templates";

/** Local hour at which the rollup goes out on the first day of the recipient's week. */
export const SEND_HOUR = 8;

const HOUR_MS = 60 * 60 * 1000;
const DAY_MS = 24 * HOUR_MS;

export interface RollupResult {
  sent: number;
  skipped: number;
  failed: number;
}

export function isRollupDue(now: Date, user: Pick<User, "timezone">): boolean {
  if (localHour(now, user.timezone) !== SEND_HOUR) return false;
  const weekStart = startOfWeek(now, user.timezone);
  // Only during the first day of the week, in the user's own time zone.
  return now.getTime() - weekStart.getTime() < DAY_MS;
}

/** Sends last week's totals to every opted-in user for whom it is now Monday, 08:00. */
export async function sendWeeklyRollups(now: Date = new Date()): Promise<RollupResult> {
  const result: RollupResult = { sent: 0, skipped: 0, failed: 0 };
  const users = await userRepo.listRollupRecipients();

  for (const user of users) {
    if (!isRollupDue(now, user)) continue;

    const weekStart = startOfWeek(now, user.timezone);
    const previousWeek = addDays(weekStart, -7);
    const totals = await transactionRepo.totalsBetween(user.id, previousWeek, weekStart);
    if (totals.length === 0) {
      result.skipped += 1;
      continue;
    }

    try {
      await sendEmail({
        to: user.email,
        subject: t("email.rollup.subject", {}, user.locale),
        text: rollupText(user, previousWeek, totals, user.timezone),
      });
      result.sent += 1;
    } catch (err) {
      result.failed += 1;
      logger.error({ err, userId: user.id }, "weekly rollup failed");
    }
  }

  return result;
}

/**
 * Ticks at the top of every hour. Each user is picked up by the one tick that
 * falls in their local send hour.
 */
export function startRollupSchedule(): () => void {
  const tick = () => {
    sendWeeklyRollups()
      .then((r) => {
        if (r.sent > 0 || r.failed > 0) logger.info(r, "weekly rollups");
      })
      .catch((err) => logger.error({ err }, "rollup tick failed"));
  };

  let interval: NodeJS.Timeout | undefined;
  const first = setTimeout(() => {
    tick();
    interval = setInterval(tick, HOUR_MS);
  }, HOUR_MS - (Date.now() % HOUR_MS));

  return () => {
    clearTimeout(first);
    if (interval) clearInterval(interval);
  };
}


--- docs/triage-runbook.md
# Issue triage runbook

Whoever is on the support rotation that week owns triage. Go through new
issues every weekday morning; every issue should have a label within one
working day of being opened.

## 1. Label it

Pick exactly one:

| Label | Use when |
| --- | --- |
| `bug` | Something documented or previously working does not work |
| `feature` | A request for new behaviour, a new option or a new format |
| `question` | The reporter wants to know how something works; no change is expected |
| `docs` | The documentation is wrong, missing something, or out of date |

Add `needs-info` as well if you cannot act on it yet. If an issue is really two
issues, ask the reporter to split it.

## 2. Reproduce (bugs only)

- Ask for the version (`GET /api/v1/health` returns it), the user's locale and
  time zone if dates or emails are involved, and a small sample file with
  personal data removed.
- Reproduce on staging with the same input before going further.
- Do not ask for real bank statements. A redacted sample with three or four
  rows is almost always enough.

## 3. Find the owning code

Reporters often name the part of the product where they saw the symptom, which
is not always where the cause is. Confirm in the code before assigning.

| Area | Start in |
| --- | --- |
| Uploads and imports | `src/api/uploads.ts`, `src/ingest/` |
| Reports and exports | `src/api/reports.ts`, `src/export/`, `src/exportUtils.ts` |
| Emails | `src/notifications/` |
| Accounts and login | `src/api/auth.ts`, `src/api/users.ts` |
| Web components | `src/components/` |
| Configuration and deploys | `config/`, `docs/CONFIG.md` |

Write the file you think is responsible in a comment on the issue, with a line
or two on why.

## 4. Prioritise

- **P1**: data loss, wrong amounts in the ledger, or a security problem. Tell
  the on-call engineer the same day.
- **P2**: a feature is broken and there is no workaround.
- **P3**: everything else, including most feature requests.

## 5. Reply

Thank the reporter, say what label and priority you gave it, and what happens
next. For questions, answer directly and close once the reporter confirms.
Never close a bug as "cannot reproduce" without asking for more information at
least once.


