--- src/db/client.ts
import { Pool, types, type PoolClient, type QueryResultRow } from "pg";
import { config } from "../config";
import { logger } from "../logger";

// Keep DATE columns as "YYYY-MM-DD" strings instead of Date objects at local midnight.
types.setTypeParser(types.builtins.DATE, (value: string) => value);
// BIGINT amounts are minor units and fit comfortably in a JS number.
types.setTypeParser(types.builtins.INT8, (value: string) => Number.parseInt(value, 10));

const pool = new Pool({
  connectionString: config.db.url,
  max: config.db.poolSize,
  statement_timeout: config.db.statementTimeoutMs,
});

pool.on("error", (err) => logger.error({ err }, "idle database client error"));

type Params = unknown[];

export interface Queryable {
  query<T extends QueryResultRow>(sql: string, params?: Params): Promise<T[]>;
}

function wrap(client: Pool | PoolClient): Queryable {
  return {
    async query<T extends QueryResultRow>(sql: string, params: Params = []): Promise<T[]> {
      const result = await client.query<T>(sql, params);
      return result.rows;
    },
  };
}

const base = wrap(pool);

export const db = {
  query: base.query,

  async one<T extends QueryResultRow>(sql: string, params: Params = []): Promise<T> {
    const rows = await base.query<T>(sql, params);
    if (rows.length !== 1) throw new Error(`Expected exactly one row, got ${rows.length}`);
    return rows[0];
  },

  async maybeOne<T extends QueryResultRow>(sql: string, params: Params = []): Promise<T | null> {
    const rows = await base.query<T>(sql, params);
    return rows[0] ?? null;
  },

  /** Runs `fn` in a transaction on a single connection; rolls back if it throws. */
  async tx<T>(fn: (q: Queryable) => Promise<T>): Promise<T> {
    const client = await pool.connect();
    try {
      await client.query("BEGIN");
      const result = await fn(wrap(client));
      await client.query("COMMIT");
      return result;
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  },

  async ping(): Promise<void> {
    await pool.query("SELECT 1");
  },

  end(): Promise<void> {
    return pool.end();
  },
};


--- src/api/errors.ts
import type { NextFunction, Request, RequestHandler, Response } from "express";
import { ZodError } from "zod";
import { pickLocale, t } from "../i18n";
import { isIngestError } from "../ingest/errors";
import { logger } from "../logger";

export class HttpError extends Error {
  constructor(
    readonly status: number,
    message: string,
    readonly details?: unknown,
  ) {
    super(message);
    this.name = "HttpError";
  }
}

export const badRequest = (message: string, details?: unknown) => new HttpError(400, message, details);
export const notFoundError = (what: string) => new HttpError(404, `${what} not found`);

type AsyncRoute = (req: Request, res: Response) => Promise<unknown>;

/** Express 4 does not forward rejected promises to error middleware, so wrap async handlers. */
export const asyncHandler =
  (fn: AsyncRoute): RequestHandler =>
  (req, res, next) => {
    fn(req, res).catch(next);
  };

export function notFound(_req: Request, res: Response): void {
  res.status(404).json({ error: "not found" });
}

// Express recognises error middleware by its four parameters, so keep `_next`.
export function errorHandler(err: unknown, req: Request, res: Response, _next: NextFunction): void {
  if (res.headersSent) {
    logger.warn({ err, requestId: res.locals.requestId }, "error after response started");
    res.end();
    return;
  }

  if (err instanceof HttpError) {
    res.status(err.status).json({ error: err.message, details: err.details });
    return;
  }

  if (err instanceof ZodError) {
    res.status(400).json({ error: "validation failed", details: err.flatten().fieldErrors });
    return;
  }

  if (isIngestError(err)) {
    // Upload content problems: translate for the caller and pass the row number through.
    const locale = pickLocale(req.header("accept-language"));
    res.status(422).json({
      error: t(err.key, err.params, locale),
      code: err.key,
      row: err.params.row ?? null,
    });
    return;
  }

  logger.error({ err, requestId: res.locals.requestId }, "unhandled error");
  res.status(500).json({ error: "internal error", requestId: res.locals.requestId });
}


--- src/util/money.ts
export const DEFAULT_CURRENCY = "EUR";

// Currencies with no minor unit. Everything else is treated as two decimals.
const ZERO_DECIMAL = new Set(["CLP", "ISK", "JPY", "KRW", "VND", "XAF", "XOF"]);

export function minorDigits(currency: string): number {
  return ZERO_DECIMAL.has(currency.toUpperCase()) ? 0 : 2;
}

export function isCurrencyCode(value: string): boolean {
  return /^[A-Z]{3}$/.test(value);
}

/**
 * Parses an amount as written in a bank export into integer minor units.
 * Accepts "1234.56", "1,234.56", "-12.5", "+3", "(12.50)" and a leading
 * currency symbol. Returns null when the value is not a number.
 */
export function parseAmount(raw: string, currency: string = DEFAULT_CURRENCY): number | null {
  let text = raw.replace(/[\s€$£¥]/g, "");
  let negative = false;

  // Accounting style: (12.50) means -12.50
  if (text.startsWith("(") && text.endsWith(")")) {
    negative = true;
    text = text.slice(1, -1);
  }
  if (text.startsWith("-")) {
    negative = !negative;
    text = text.slice(1);
  } else if (text.startsWith("+")) {
    text = text.slice(1);
  }

  text = text.replace(/,/g, "");
  if (!/^\d+(\.\d+)?$/.test(text)) return null;

  const value = Math.round(Number(text) * 10 ** minorDigits(currency));
  return negative ? -value : value;
}

export function toMajor(amount: number, currency: string): number {
  return amount / 10 ** minorDigits(currency);
}

/** Plain decimal string, e.g. -1250 EUR -> "-12.50". Used in CSV exports. */
export function formatMinor(amount: number, currency: string): string {
  return toMajor(amount, currency).toFixed(minorDigits(currency));
}

/** Localised with symbol, e.g. "€12.50" or "12,50 €". Used in emails and the UI. */
export function formatMoney(amount: number, currency: string, locale = "en"): string {
  return new Intl.NumberFormat(locale, { style: "currency", currency }).format(toMajor(amount, currency));
}


