      duplicates: found.duplicateCount,
      error: found.errorKey ? t(found.errorKey, found.errorParams ?? {}, locale) : null,
      row: found.errorParams?.row ?? null,
      createdAt: found.createdAt,
      finishedAt: found.finishedAt,
    });
  }),
);


